(function(){
'use strict';
const FLOW='20260915-live-chat-v3';
const RESET='20260915-live-chat-v3-reset2';
function isTrip(){return !!document.getElementById('tripWizard')||location.pathname.indexOf('/trip/new')===0;}
function firstName(p){return String(p.first_name||p.name||p.full_name||'').trim().split(/\s+/)[0]||'';}
function removeLegacy(){document.querySelectorAll('#vacationTypeGate,.vacation-type-gate,.vacation-type-grid,.trip-back-bar').forEach(x=>x.remove());const w=document.getElementById('tripWizard');if(w)w.style.display='none';}
function style(){if(document.getElementById('ariella-live-chat-style'))return;const s=document.createElement('style');s.id='ariella-live-chat-style';s.textContent='#tripWizard,#vacationTypeGate,.vacation-type-gate,.vacation-type-grid,.trip-back-bar{display:none!important}#ariellaDesktopChat{width:min(1280px,92%);margin:18px auto 40px;direction:rtl;font-family:Arial,"Segoe UI",sans-serif}#ariellaDesktopChat .ac-shell{display:grid;grid-template-columns:minmax(0,2fr) minmax(300px,.85fr);gap:22px}.ac-chat,.ac-summary{background:#fffaf2;border:1px solid rgba(201,154,63,.38);border-radius:22px;overflow:hidden}.ac-chat{height:min(650px,calc(100vh - 150px));min-height:520px;display:flex;flex-direction:column}.ac-head{display:flex;align-items:center;gap:10px;padding:14px;background:#123437;color:#fff}.ac-messages{flex:1;min-height:0;padding:18px 14px;display:flex;flex-direction:column;gap:12px;overflow-y:auto}.ac-row{display:flex;gap:8px;align-items:flex-start}.ac-row.user{justify-content:flex-start;flex-direction:row-reverse}.ac-bubble{max-width:84%;padding:11px 13px;border-radius:14px;background:#fff;border:1px solid #eadfc8;white-space:pre-line;line-height:1.55}.ac-row.user .ac-bubble{background:#dff3f5;border-color:#b7dde1}.ac-compose{padding:10px;border-top:1px solid #eadfc8;background:#fff;display:flex;gap:10px}.ac-compose textarea{flex:1;min-height:48px;max-height:120px;border:1px solid #d9cdb8;border-radius:14px;padding:12px;font:inherit;resize:none}.ac-send{height:48px;min-width:68px;border:0;border-radius:13px;background:#0b8f9c;color:#fff;font-weight:800}.ac-summary{padding:18px}.ac-detail{padding:9px 0;border-bottom:1px solid #eee5d5}.ac-detail b{display:block}.ac-detail span{color:#7f776b;font-size:14px}@media(max-width:899px){#ariellaDesktopChat{width:100%;margin:0 auto 24px;padding:8px 10px}.ac-shell{display:flex!important;flex-direction:column}.ac-chat{height:calc(100dvh - 125px);min-height:500px;border-radius:16px}.ac-summary{border-radius:16px}}';document.head.appendChild(s);}
function makeChat(){let old=document.getElementById('ariellaDesktopChat');if(old)old.remove();const c=document.createElement('section');c.id='ariellaDesktopChat';c.dataset.engineOwner='live-chat-v3';c.innerHTML='<div class="ac-shell"><div class="ac-chat"><div class="ac-head"><strong>אריאלה — סוכנת הנסיעות האישית שלך</strong></div><div class="ac-messages" id="ariellaChatMessages"></div><div class="ac-compose"><textarea id="ariellaChatInput" rows="1" aria-label="כתיבת הודעה"></textarea><button id="ariellaChatSend" class="ac-send" type="button">שליחה</button></div></div><aside class="ac-summary"><strong>החופשה שלי</strong><div class="ac-detail"><b>פרטים שנאספו בשיחה</b><span id="ariellaLiveSummary">עדיין לא נאספו פרטים</span></div></aside></div>';const w=document.getElementById('tripWizard'),m=document.querySelector('main');if(w&&w.parentNode)w.parentNode.insertBefore(c,w);else if(m)m.appendChild(c);return c;}
async function loadMemberName(profile){if(firstName(profile))return;try{const r=await fetch('/account',{credentials:'same-origin',cache:'no-store'});if(!r.ok)return;const html=await r.text(),doc=new DOMParser().parseFromString(html,'text/html'),text=(doc.body&&doc.body.innerText)||'',m=text.match(/שלום\s*[,،:]?\s*([^\s,!.]+)/);if(m&&m[1])profile.first_name=m[1].trim();}catch(e){}}
function controller(chat){const input=chat.querySelector('#ariellaChatInput'),send=chat.querySelector('#ariellaChatSend'),messages=chat.querySelector('#ariellaChatMessages'),summary=chat.querySelector('#ariellaLiveSummary');let profile={},history=[],busy=false;try{const s=JSON.parse(localStorage.getItem('ariellaChatState:v4')||'null');if(s)profile=s.profile||{};if(localStorage.getItem('ariellaChatOneTimeReset')!==RESET){const keep={};['first_name','last_name','name','full_name','gender','sex','phone','email','member_id','user_id','departure_airport'].forEach(k=>{if(profile[k]!=null&&profile[k]!=='')keep[k]=profile[k];});profile=keep;history=[];localStorage.setItem('ariellaChatOneTimeReset',RESET);}else if(s&&s.flow===FLOW&&Array.isArray(s.history))history=s.history;}catch(e){}
const save=()=>{try{localStorage.setItem('ariellaChatState:v4',JSON.stringify({profile,history:history.slice(-60),flow:FLOW,saved_at:new Date().toISOString()}));}catch(e){}};
const add=(role,text)=>{if(!String(text||'').trim())return;const r=document.createElement('div');r.className='ac-row '+(role==='assistant'?'bot':'user');const b=document.createElement('div');b.className='ac-bubble';b.textContent=text;r.appendChild(b);messages.appendChild(r);messages.scrollTop=messages.scrollHeight;};
const drawSummary=()=>{const bits=[];const d=profile.destinations;if(d)bits.push('יעד: '+(Array.isArray(d)?d.join(', '):d));if(profile.outbound_month)bits.push('חודש: '+profile.outbound_month);if(profile.departure_date)bits.push('יציאה: '+profile.departure_date);if(profile.return_date)bits.push('חזרה: '+profile.return_date);if(profile.adults)bits.push('מבוגרים: '+profile.adults);if(profile.children)bits.push('ילדים: '+profile.children);summary.textContent=bits.join(' · ')||'עדיין לא נאספו פרטים';};
async function start(){messages.innerHTML='';if(history.length){history.forEach(x=>add(x.role,x.content));drawSummary();return;}await loadMemberName(profile);const n=firstName(profile),g=(n?'היי '+n+', ':'היי, ')+'איזה כיף שהתחברת 😊\nאני אריאלה. מה בא לך לתכנן?';add('assistant',g);history.push({role:'assistant',content:g});save();drawSummary();}
async function talk(){const text=input.value.trim();if(!text||busy)return;busy=true;send.disabled=true;input.value='';add('user',text);const prior=history.slice(-18);history.push({role:'user',content:text});save();try{const r=await fetch('/api/ariella/chat-clean',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',cache:'no-store',body:JSON.stringify({message:text,history:prior,profile})});let data={};try{data=await r.json();}catch(e){}if(!r.ok||data.status!=='success')throw new Error(data.message||'chat error');if(data.engine_version!=='live-chat-v3'){add('assistant','יש כרגע אי־התאמה בגרסת הצ׳ט. רענני את הדף בעוד רגע.');console.error('Expected live-chat-v3, got',data.engine_version);return;}document.documentElement.dataset.ariellaEngine=data.engine_version;profile=data.profile||profile;drawSummary();const reply=String(data.reply||'').trim();if(reply){add('assistant',reply);history.push({role:'assistant',content:reply});save();}}catch(e){add('assistant','יש כרגע תקלה זמנית בחיבור לצ׳ט. נסי שוב בעוד רגע.');}finally{busy=false;send.disabled=false;input.focus();}}
send.addEventListener('click',e=>{e.preventDefault();talk();});input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();talk();}});start();}
function boot(){if(!isTrip())return;removeLegacy();style();controller(makeChat());}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();